try:
    sale_mask = (df['row_kind'] == 'sale') & (df['Currency'] == 'USD')
    return_mask = (df['row_kind'] == 'return') & (df['Currency'] == 'USD')
    net_mask = sale_mask | return_mask

    net_df = df[net_mask].copy()

    order_revenue = net_df.groupby('Name').agg(
        revenue=('Lineitem price', lambda x: (net_df.loc[x.index, 'Lineitem quantity'] * x).sum()),
        discount=('Discount Amount', 'first'),
        country=('Shipping Country', 'first')
    ).reset_index()

    order_revenue['net_sales'] = order_revenue['revenue'] - order_revenue['discount'].fillna(0)

    country_aov = order_revenue.groupby('country').agg(
        total_net=('net_sales', 'sum'),
        order_count=('Name', 'count')
    ).reset_index()
    country_aov['aov'] = country_aov['total_net'] / country_aov['order_count']
    country_aov = country_aov.sort_values('aov', ascending=False).head(10)

    aov_results = [
        {"name": str(row['country']), "value": round(float(row['aov']), 4)}
        for _, row in country_aov.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Name",
        "aggregation": "ratio",
        "label": "avg_order_value_net_sales_per_order",
        "results": aov_results
    })

    order_count_results = [
        {"name": str(row['country']), "value": int(row['order_count'])}
        for _, row in country_aov.iterrows()
    ]
    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Name",
        "aggregation": "count",
        "label": "order_count",
        "results": order_count_results
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

